    /// Exits one state (W3C SCXML 3.9): records its histories, runs its `<onexit>`,
    /// cancels its invocations and removes it from the configuration, in
    /// §scxml-D-exitStates's order.
    public func executeExitActions(_ state: StaticHostKvState, engine: Engine<StaticHostKvPolicy>, configurationBeforeExit: [StaticHostKvState]) {
        // §scxml-D-exitStates orders one state's exit as onexit, then cancelInvoke,
        // then configuration.delete(s), so `In(s)` inside s's own handler is true:
        // the <onexit> switch comes first and the removal from the configuration
        // last.
        switch state {
        default:
            break  // No exit actions
        }
        // W3C SCXML 6.4: the invocations of an exited state end with it: one not yet
        // started never starts, and a running session is exited, its states' <onexit>
        // run, before it is dropped. What that exit sends to #_parent is dropped with
        // it (test252).
        switch state {
        case .deleting:
            cancelInvokesForState(&pendingInvokes, .deleting)
            engine.cancelHostInvoke(processorType: "sce-host-kv-delete", invokeID: "del")
        case .getting:
            cancelInvokesForState(&pendingInvokes, .getting)
            engine.cancelHostInvoke(processorType: "sce-host-kv-get", invokeID: "get")
        case .putting:
            cancelInvokesForState(&pendingInvokes, .putting)
            engine.cancelHostInvoke(processorType: "sce-host-kv-put", invokeID: "put")
        case .walking:
            cancelInvokesForState(&pendingInvokes, .walking)
            engine.cancelHostInvoke(processorType: "sce-host-kv-next-key", invokeID: "walk")
        default:
            break  // No invocations to cancel
        }
    }



